    image: "",
    brand: "",
    model: "",
    year: "",
    price: "",
    description: "",
  });

  useEffect(() => {
    loadCars();
  }, [db]);

  async function loadCars() {
    try {
      const allCars = await db.getAllAsync<Car>(
        "SELECT * FROM cars ORDER BY id DESC",
      );
      setCars(allCars);
    } catch (error) {
      console.error("Load Cars Error:", error);
    }
  }

  async function pickImage() {
    try {
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ["images"],
        allowsEditing: true,
        aspect: [16, 9],
        quality: 0.8,
      });
      if (!result.canceled) {
        setFormData({ ...formData, image: result.assets[0].uri });
      }
    } catch (error) {
      Alert.alert("Error", "Gagal memilih gambar");
    }
  }

  async function handleSave() {
    if (!formData.brand || !formData.model || !formData.price) {
      Alert.alert(
        "Peringatan",
        "Mohon isi semua field wajib (Brand, Model, Harga)",
      );
      return;
    }

    try {
      if (editingId) {
        await db.runAsync(
          "UPDATE cars SET image = ?, brand = ?, model = ?, year = ?, price = ?, description = ? WHERE id = ?",
          [
            formData.image,
            formData.brand,
            formData.model,
            formData.year,
            formData.price,
            formData.description,
            editingId,
          ],
        );
      } else {
        await db.runAsync(
          "INSERT INTO cars (image, brand, model, year, price, description) VALUES (?, ?, ?, ?, ?, ?)",
          [
            formData.image,
            formData.brand,
            formData.model,
            formData.year,
            formData.price,
            formData.description,
          ],
        );
      }
      loadCars();
      resetForm();
    } catch (error) {
      console.error("Save Error:", error);
      Alert.alert("Error", "Gagal menyimpan data ke database.");
    }
  }

  function handleEdit(car: Car) {
    setEditingId(car.id);
    setFormData({
      image: car.image,
      brand: car.brand,
      model: car.model,
      year: car.year,
      price: car.price,
      description: car.description,
    });
    setVisible(true);
  }

  function handleDelete(id: number) {
    Alert.alert("Hapus Mobil", "Apakah Anda yakin ingin menghapus mobil ini?", [
      { text: "Batal", style: "cancel" },
      {
        text: "Hapus",
        style: "destructive",
        onPress: async () => {
          try {
            await db.runAsync("DELETE FROM cars WHERE id = ?", [id]);
            loadCars();
          } catch (error) {
            Alert.alert("Error", "Gagal menghapus data.");
          }
        },
      },
    ]);
  }

  function resetForm() {
    setFormData({
      image: "",
      brand: "",
      model: "",
      year: "",
      price: "",
      description: "",
    });
    setEditingId(null);
    setVisible(false);
  }

  const filteredCars = cars.filter(
    (car) =>
      car.brand.toLowerCase().includes(searchQuery.toLowerCase()) ||
      car.model.toLowerCase().includes(searchQuery.toLowerCase()),
  );

interface Car {
  id: number;
  image: string;
  brand: string;
  model: string;
  year: string;
  price: string;
  description: string;
}


