import jwt from "jsonwebtoken";

export function roleMiddleware(...allowedRoles) {
    return function (req, res, next) {
    if (!req.user) {
        return res.status(401).json({
            message: "Token tidak ada"
        });
    }

    if (req.user.role === "super_admin") {
        return next();
    }

    if (!allowedRoles.includes(req.user.role)) {
        return res.status(403).json({
            message: "Anda tidak memiliki akses"
        });
    }

    next();
    };
}

jelasin

Kode ini adalah otak utama di balik **Sistem Hak Akses (RBAC)** di aplikasimu. Kode ini bertugas sebagai **"Satpam Penjaga Pintu"** yang akan menyeleksi apakah seorang pengguna boleh masuk ke URL tertentu atau tidak berdasarkan jabatannya (role).

Mari kita bedah baris per baris dengan analogi supaya gampang dipahami:

### 1. Fungsi Utama dan Parameter Rest `...`
```javascript
export function roleMiddleware(...allowedRoles) {
```
*   `...allowedRoles` (titik tiga) ini namanya *Rest Parameter*.
*   Fungsinya mengubah apa pun parameter yang kamu masukkan menjadi **Array**.
*   Contohnya di `index.js`, kalau kamu nulis `roleMiddleware("admin", "user")`, maka si `allowedRoles` akan berubah bentuk otomatis jadi array: `["admin", "user"]`.

### 2. Mengembalikan Middleware (Closure)
```javascript
    return function (req, res, next) {
```
*   Kenapa di dalam fungsi ada fungsi lagi (`return function`)? Karena Express.js itu "meminta" format khusus untuk Middleware, yaitu harus punya `(req, res, next)`.
*   Jadi `roleMiddleware` itu cuma *pabrik* yang bertugas membuat/mencetak middleware sungguhan sesuai role yang diizinkan.

### 3. Pengecekan 1: Apakah sudah Login?
```javascript
    if (!req.user) {
        return res.status(401).json({
            message: "Token tidak ada"
        });
    }
```
*   Satpam mengecek: *"Eh, kamu bawa ID Card (Token) nggak?"*
*   `req.user` ini seharusnya didapat dari `authMiddleware` sebelumnya. Kalau `req.user` kosong, artinya orang tersebut belum login atau tokennya mati. Langsung tolak (401 Unauthorized).

### 4. Pengecekan 2: Jalur VIP (Super Admin)
```javascript
    if (req.user.role === "super_admin") {
        return next();
    }
```
*   Satpam mengecek jabatan: *"Oh, kamu Bos Besar (`super_admin`)? Silakan langsung masuk, Bos!"*
*   Ini adalah fitur **Bypass**. Apapun URL yang diakses, kalau rolenya `super_admin`, dia nggak akan dicek aturan selanjutnya. Dia langsung disuruh jalan terus (`next()`).

### 5. Pengecekan 3: Validasi Role Sesuai Rute
```javascript
    if (!allowedRoles.includes(req.user.role)) {
        return res.status(403).json({
            message: "Anda tidak memiliki akses"
        });
    }
```
*   Kalau yang datang **bukan** `super_admin`, maka Satpam akan mengecek buku daftarnya (array `allowedRoles`).
*   Fungsi `.includes()` mengecek: *"Apakah jabatan orang ini (req.user.role) tercatat di buku daftar (allowedRoles) yang boleh masuk ruangan ini?"*
*   Kalau `!includes` (tidak ada di daftar), langsung tolak dan kasih pesan error **403 (Forbidden)**.

### 6. Lolos Sensor
```javascript
    next();
```
*   Kalau dia bukan super admin, tapi rolenya tercatat di daftar (misal admin mau masuk rute admin), maka Satpam mempersilakan masuk.
*   `next()` artinya *"Lanjut ke proses controller berikutnya (misalnya fungsi ambil data ke database)."*

---

**Kesimpulan Cepat:**
Kode ini mengecek: **"Apakah kamu punya token? Kalau kamu super_admin, masuk aja. Tapi kalau bukan, biarku cek dulu apakah jabatanmu ada di daftar izin rute ini."**

Saya telah menambahkan validasi menggunakan `if-else` untuk mengecek apakah `id` yang dimasukkan berupa angka atau bukan di file [barangRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/barangRoutes.js:0:0-0:0) dan [siswaRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/siswaRoutes.js:0:0-0:0).

### Perubahan yang dilakukan:
1.  **Validasi Angka**: Menggunakan `!isNaN(id)` untuk memastikan parameter ID adalah angka.
2.  **Status Code**: 
    *   Jika bukan angka, akan mengembalikan status **400 (Bad Request)** dengan pesan "ID harus berupa angka!".
    *   Jika angka, proses akan dilanjutkan (status 200 untuk GET dan 418 untuk DELETE di barang).

#### Contoh implementasi di [barangRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/barangRoutes.js:0:0-0:0):
```javascript
barangRoutes.get("/:id", (req, res) => {
  const id = req.params.id;
  if (!isNaN(id)) {
    res.send("data barang ke " + id);
  } else {
    res.status(400).json({ message: "ID harus berupa angka!" });
  }
});
```

Saya juga menerapkan logika yang sama pada route `DELETE` dan juga pada [siswaRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/siswaRoutes.js:0:0-0:0) agar konsisten. Apakah ada yang ingin ditambahkan lagi?

Siap, saya sudah mengubahnya menjadi yang lebih simpel. Sekarang validasinya hanya menggunakan fungsi `Number()` untuk mengecek apakah ID tersebut bisa dianggap sebagai angka:

```javascript
if (Number(id)) {
  // berhasil
} else {
  // error 400
}
```

Ini cara yang sangat simpel karena jika `id` adalah teks (seperti "abc"), `Number(id)` akan menghasilkan `NaN` yang dianggap `false`. Jika `id` adalah angka (selain 0), ia akan dianggap `true`.

Sudah saya terapkan di [barangRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/barangRoutes.js:0:0-0:0) dan [siswaRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/siswaRoutes.js:0:0-0:0). Ada lagi yang perlu disesuaikan?

Saya sudah menambahkan validasi untuk mengecek apakah data JSON yang dikirim kosong atau tidak pada route `POST` di [barangRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/barangRoutes.js:0:0-0:0).

### Perubahan yang dilakukan:
1.  **Mengaktifkan Middleware JSON**: Di file [app.js](cci:7://file:///d:/laragon/www/express-playground/app.js:0:0-0:0), saya menambahkan `app.use(express.json())` agar server bisa membaca data JSON yang dikirim di body request.
2.  **Validasi Body**: Di file [barangRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/barangRoutes.js:0:0-0:0), saya menambahkan pengecekan menggunakan `Object.keys(req.body).length > 0`.
    *   Jika ada datanya: Mengembalikan status **201** dengan pesan "barang tersimpan!".
    *   Jika kosong: Mengembalikan status **400** dengan pesan "data json tidak boleh kosong!".

#### Contoh kode di [barangRoutes.js](cci:7://file:///d:/laragon/www/express-playground/routes/barangRoutes.js:0:0-0:0):
```javascript
barangRoutes.post("/", (req, res) => {
  if (Object.keys(req.body).length > 0) {
    res.status(201).json({ message: "barang tersimpan!", data: req.body });
  } else {
    res.status(400).json({ message: "data json tidak boleh kosong!" });
  }
});
```

Apakah ada bagian lain yang ingin ditambahkan?

Pertanyaan yang bagus! Alasan kenapa kita harus pakai `Object.keys(req.body).length` adalah karena sifat **Object di JavaScript**:

### 1. Object Kosong itu Tetap "True"
Di JavaScript, sebuah object kosong `{}` kalau dicek langsung di `if`, nilainya dianggap **true**.
```javascript
if ({}) { 
  console.log("Ini jalan!"); // Tetap muncul meskipun kosong
}
```
Jadi, kalau kita cuma tulis `if (req.body)`, kodenya akan selalu menganggap data itu ada (berhasil), padahal isinya cuma `{}`.

### 2. Kenapa pakai `Object.keys`?
`Object.keys(req.body)` gunanya untuk mengambil semua "kunci" atau "nama field" yang ada di dalam JSON tersebut dan merubahnya menjadi **Array**.
*   Kalau JSON-nya: `{"nama": "meja"}` -> Hasilnya: `["nama"]` (punya 1 data)
*   Kalau JSON-nya: `{}` -> Hasilnya: `[]` (Array kosong)

### 3. Kenapa pakai `.length`?
Karena `Object.keys` menghasilkan Array, kita bisa cek jumlah isinya pakai `.length`. 
*   Jika `.length` adalah **0**, berarti JSON-nya kosong.
*   Jika lebih dari **0**, berarti ada datanya.

---

### Apakah ada cara yang lebih "Simple"?
Kalau kamu tidak mau pakai `Object.keys().length`, kamu bisa cek salah satu field yang **wajib** diisi. Misalnya kamu mewajibkan harus ada "nama":

```javascript
barangRoutes.post("/", (req, res) => {
  // Langsung cek field spesifik
  if (req.body.nama) { 
    res.status(201).json({ message: "barang tersimpan!" });
  } else {
    res.status(400).json({ message: "Nama barang harus diisi!" });
  }
});
```

Cara ini lebih simpel kelihatannya, tapi hanya mengecek satu field saja, bukan mengecek keseluruhan JSON. Mau diubah ke cara yang mana?

import { useEffect, useState } from "react";
import { Alert, ScrollView, View } from "react-native";
import {
  Appbar,
  Button,
  Card,
  Dialog,
  Divider,
  IconButton,
  List,
  Portal,
  SegmentedButtons,
  Text,
  TextInput,
} from "react-native-paper";

import { supabase } from "@/lib/supabase";

export default function Index() {
  const [dialogVisible, setDialogVisible] = useState(false);
  const [formType, setFormType] = useState<"in" | "out">("out");
  const [formAmount, setFormAmount] = useState("0");
  const [formDescription, setFormDescription] = useState("");
  const [transactions, setTransactions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTransactions();
  }, []);

  async function fetchTransactions() {
    setLoading(true);
    const { data, error } = await supabase
      .from("transactions")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      Alert.alert("Gagal mengambil data", error.message);
    } else {
      setTransactions(data || []);
    }
    setLoading(false);
  }

  async function handleDelete(id: string) {
    const { error } = await supabase.from("transactions").delete().eq("id", id);
    if (error) {
      Alert.alert("Gagal menghapus", error.message);
    } else {
      fetchTransactions();
    }
  }

  const totalIn = transactions
    .filter((t) => t.type === "in")
    .reduce((acc, t) => acc + parseInt(t.amount), 0);
  const totalOut = transactions
    .filter((t) => t.type === "out")
    .reduce((acc, t) => acc + parseInt(t.amount), 0);
  const balance = totalIn - totalOut;

  const formatCurrencyInput = (value: string) => {
    // Remove all non-numeric characters
    const numericValue = value.replace(/[^0-9]/g, "");
    // Format with dots as thousand separators
    return numericValue.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  };

  async function handleAdd() {
    // Remove dots before parsing to number
    const numericAmount = formAmount.replace(/\./g, "");
    const amount = parseInt(numericAmount);
    if (!amount || amount <= 0) {
      return Alert.alert("Jumlah tidak valid");
    }
    if (formDescription == "") {
      return Alert.alert("Deskripsi tidak boleh kosong");
    }

    const { error } = await supabase.from("transactions").insert({
      type: formType,
      amount: amount, // Use the parsed number
      description: formDescription,
    });

    if (error) {
      console.log("Supabase error:", error);
      Alert.alert("Gagal menambahkan transaksi", error.message);
    } else {
      console.log("Transaction added successfully");
      setFormAmount("0");
      setFormDescription("");
      fetchTransactions();
    }
  }

  return (
    <View style={{ flex: 1, backgroundColor: "#000000" }}>
      <ScrollView style={{ flex: 1 }}>
        <Appbar.Header style={{ backgroundColor: "#000000" }}>
          <Appbar.Content title="Budget App" titleStyle={{ color: "white" }} />
          <Appbar.Action
            icon="plus"
            color="white"
            onPress={() => {
              setDialogVisible(true);
            }}
          />
        </Appbar.Header>

        <Card style={{ margin: 16, backgroundColor: "#1e1e1e", borderRadius: 16 }}>
          <Card.Content>
            <Text variant="labelSmall" style={{ color: "#aaa" }}>
              Sisa Saldo
            </Text>
            <Text
              variant="displaySmall"
              style={{
                color: balance >= 0 ? "#4CAF50" : "#FF5252",
                fontWeight: "bold",
                marginVertical: 4,
              }}
            >
              Rp {balance.toLocaleString("id-ID")}
            </Text>
